bookInfoRule.init:
$..book_id
<js>
let res = result[0];
let media = res.split("_")[1] || 'fanqie'
let bookid = res.split("_")[0];
let sjy = '';
let info;
let bookUrl = '';
let lx = '';
let zxtime = '';
let zxzj = '';
let sy = '';
let jj = '';
try {
	       function setArgument(key, value) {
        let open_argument = source.getVariable();
        open_argument = getArguments(open_argument, '');
        open_argument[key] = value;
        open_argument = JSON.stringify(open_argument);
        source.setVariable(open_argument);
        return open_argument;
    }

    function gets_key() {
        var servers = String(source.bookSourceUrl);
        const serverList = servers.split('\n');

        for (let server of serverList) {
            let keys = String(cookie.getCookie(server)) || String(java.getCookie(server));
            if (keys) {
                let keyParts = keys.split('secretKey=');
                if (keyParts.length > 1) {
                    keys = keyParts[keyParts.length - 1];
                    setArgument('key', keys);
                    return keys;
                }
            }
        }
        return '';
    }

    let open_argument = source.getVariable();
    let base_url = getArguments(open_argument, 'server');
    let ms = getArguments(open_argument, 'media');
    let key = getArguments(open_argument, 'key');
    if (!key) {
        key = gets_key();
    }

    var tishi = '&nbsp;&nbsp;当前搜索模式：' + ms + '\n\n如需切换,请点击登陆进行切换\n切换之后需要重新搜索！\n\n\u200b'
    if (media == 'fanqie' || media == 'juxiaoshuo') {
        try {
            info = JSON.parse(java.ajax(`${base_url}/novel_detail?&bookid=${bookid}`));
          try {
                let shuyuan = info.shuyuan;
                if (shuyuan) {
                    let n = 0;
                    let v = String(book.getVariable("custom"));
                    let x = v.match(/^\d+$/) ? v : n;
                    x = parseInt(x) < shuyuan.length ? x : n;
                    bookUrl = shuyuan[x];
                    bookUrl = `${base_url}/detail?bookId=${bookUrl}_juxiaoshuo`;
                    sjy = `🎯当前书源【${x}】：${shuyuan[x]}`;
                    sy = info.sy;
                    lx= info.lx;
                    zxtime= info.zxtime;
                    zxzj= info.zxzj;
                    jj = info.abstract;
                    jj = `${lx}
${zxzj}
${zxtime}
\u200b
${jj}
\u200b
${sjy}
${sy}`
info = {'abstract': jj}
                }
            } catch (error) {
                info = {'abstract': ""}
            }
        } catch (error) {
            info = {'abstract': ""}
        }
    } else {
        info = {'abstract': ""}
    }

    if (!key) {
        jj = '\n\n❌️当前用户未填写密钥，请先输入密钥\n密钥获取途径，书籍详情页，点击右上角点击登陆，获取后，填写，再次刷新详情页'
    } else if (!info.abstract) {
        jj = ""
    } else {
        jj = info.abstract
    }
if (!jj){tishi=''}
    let data = {
    	   tishi:tishi,
        info: jj,
        bookUrl: bookUrl
    };
    JSON.stringify(data);
} catch (error) {
    JSON.stringify({info: '', bookUrl: ''});
}
</js>

